def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Default defector behaviour: defect unless we have observed the recipient
    # cooperating on their most recent turn.
    for obs in observations:
        if obs['agent_id'] == recipient_id:
            # If the recipient's last known action was a donation, cooperate now.
            if obs['action']:
                return True
            else:
                return False
    # No information about this recipient -> defect.
    return False
